CREATE TABLE IF NOT EXISTS company_treasuries (company_id TEXT PRIMARY KEY REFERENCES commerce_companies(id), balance INTEGER NOT NULL DEFAULT 0 CHECK(balance>=0));
CREATE TABLE IF NOT EXISTS company_employees (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES commerce_companies(id), employee_id TEXT NOT NULL REFERENCES users(id), position TEXT NOT NULL, salary INTEGER NOT NULL CHECK(salary>=0), status TEXT NOT NULL DEFAULT 'offered' CHECK(status IN ('offered','active','rejected','ended')), accepted_at TEXT, ended_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS company_salary_payments (id TEXT PRIMARY KEY, employment_id TEXT NOT NULL REFERENCES company_employees(id), period TEXT NOT NULL, amount INTEGER NOT NULL CHECK(amount>0), actor_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(employment_id,period));
CREATE TABLE IF NOT EXISTS company_treasury_movements (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES company_treasuries(company_id), personal_account_id TEXT NOT NULL REFERENCES bank_accounts(id), actor_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL CHECK(kind IN ('deposit','withdraw')), amount INTEGER NOT NULL CHECK(amount>0), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS court_attachment_data (attachment_id TEXT PRIMARY KEY REFERENCES court_attachments(id), content_base64 TEXT NOT NULL);